style.css:
@-moz-document domain("youtube.com") {
/* =========================
   THEME VARIABLES (tweakable)
   ========================= */
:root {
  /* Glass look */
  --glass-bg: rgba(20, 20, 25, 0.35);
  --glass-bg-strong: rgba(20, 20, 25, 0.55);
  --glass-stroke: rgba(255, 255, 255, 0.12);
  --blur: 22px;

  /* Text & accent */
  --txt: #e9ecf1;
  --txt-dim: #c9ced8;
  --accent: #0a84ff; /* macOS blue */

  /* Cards & radius */
  --card-bg: rgba(28, 28, 33, 0.45);
  --radius: 16px;

  /* Shadows */
  --shadow-1: 0 8px 24px rgba(0,0,0,.25);
  --shadow-2: 0 2px 8px rgba(0,0,0,.25);

  /* Compact density? (0 = normal, -2px = tighter) */
  --compact-y: 0px;

  /* macOS system font stack */
  --font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, Inter, "Helvetica Neue", Arial, sans-serif;
}

/* Optional: light mode adaptation (if user forces light theme on YT) */
html[dark="false"] :root, html[dark-theme="false"] :root {
  --glass-bg: rgba(255, 255, 255, 0.45);
  --glass-bg-strong: rgba(255, 255, 255, 0.75);
  --glass-stroke: rgba(0, 0, 0, 0.1);
  --txt: #111318;
  --txt-dim: #3a3d45;
  --card-bg: rgba(255, 255, 255, 0.55);
}

/* Global typography */
html, body, ytd-app, #content, #page-manager {
  font-family: var(--font) !important;
  letter-spacing: 0.01em;
  -webkit-font-smoothing: antialiased;
  color: var(--txt) !important;
}

/* Remove harsh solid backgrounds for the glass look */
ytd-app,
#background.ytd-masthead,
#guide-content.ytd-app,
#content, #page-manager {
  background: transparent !important;
}

/* App background: subtle gradient + blurred wallpaper feel */
html {
  background:
    radial-gradient(1200px 800px at 15% 10%, rgba(10,132,255,0.08), transparent 60%),
    radial-gradient(1000px 700px at 85% 90%, rgba(255, 55, 95, 0.08), transparent 60%),
    linear-gradient(145deg, #0d0e12, #141620 65%, #0f1118) fixed !important;
}

/* =========================
   HEADER (masthead) → glass bar + mac traffic lights
   ========================= */
ytd-masthead, #masthead-container, #masthead {
  backdrop-filter: blur(var(--blur));
  -webkit-backdrop-filter: blur(var(--blur));
  background: var(--glass-bg) !important;
  border-bottom: 1px solid var(--glass-stroke) !important;
  box-shadow: var(--shadow-2);
}

#masthead-container {
  position: sticky !important;
  top: 0;
  z-index: 2000;
}

#masthead-container .ytd-masthead {
  position: relative !important;
}

/* macOS traffic lights (pure CSS dots, top-left of header) */
#masthead-container .ytd-masthead::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 14px;
  width: 44px;
  height: 14px;
  border-radius: 999px;
  background:
    radial-gradient(circle at 7px 7px, #ff5f57 0 6px, transparent 7px),
    radial-gradient(circle at 22px 7px, #ffbd2e 0 6px, transparent 7px),
    radial-gradient(circle at 37px 7px, #28c840 0 6px, transparent 7px);
  opacity: .95;
  pointer-events: none;
}

/* Move the logo a bit right to avoid overlap with traffic lights */
#start.ytd-masthead {
  padding-left: 60px !important;
}

/* Search box → glass pill */
ytd-searchbox,
#search-form {
  border-radius: 999px !important;
  overflow: hidden;
  border: 1px solid var(--glass-stroke) !important;
  background: var(--glass-bg) !important;
  backdrop-filter: blur(calc(var(--blur) * .6));
  -webkit-backdrop-filter: blur(calc(var(--blur) * .6));
}

/* =========================
   LEFT GUIDE (sidebar)
   ========================= */
#guide-content.ytd-app,
ytd-guide-renderer {
  backdrop-filter: blur(var(--blur));
  -webkit-backdrop-filter: blur(var(--blur));
  background: var(--glass-bg-strong) !important;
  border-right: 1px solid var(--glass-stroke) !important;
}

ytd-guide-section-renderer,
ytd-guide-entry-renderer {
  border-radius: var(--radius);
}

ytd-guide-entry-renderer:hover {
  background: rgba(255,255,255,.06) !important;
}

/* =========================
   CONTENT CARDS (home/feed)
   ========================= */
ytd-rich-grid-media, ytd-video-renderer, ytd-compact-video-renderer {
  border-radius: var(--radius) !important;
  background: var(--card-bg) !important;
  backdrop-filter: blur(calc(var(--blur) * .4));
  -webkit-backdrop-filter: blur(calc(var(--blur) * .4));
  border: 1px solid var(--glass-stroke) !important;
  box-shadow: var(--shadow-1);
  overflow: hidden;
}

/* Thumbnails rounded */
ytd-thumbnail, ytd-thumbnail #thumbnail, ytd-thumbnail ytd-thumbnail-overlay-side-panel-renderer {
  border-radius: calc(var(--radius) - 4px) !important;
  overflow: hidden !important;
}

/* Video titles & meta */
#video-title,
#channel-name, .ytd-video-meta-block, .metadata-snippet-container {
  color: var(--txt) !important;
  opacity: .95;
}

/* Compact vertical spacing */
ytd-rich-item-renderer {
  margin-top: calc(12px + var(--compact-y)) !important;
  margin-bottom: calc(12px + var(--compact-y)) !important;
}

/* =========================
   WATCH PAGE
   ========================= */
ytd-watch-flexy {
  --ytd-watch-flexy-sidebar-width: 420px !important;
}

ytd-watch-flexy[theater] #player-theater-container,
#player-container-outer, #player-container-inner {
  border-radius: var(--radius) !important;
  overflow: hidden !important;
  box-shadow: var(--shadow-1);
}

/* Player chrome glass */
.ytp-chrome-bottom, .ytp-gradient-bottom, .ytp-gradient-top {
  backdrop-filter: blur(calc(var(--blur) * .5)) !important;
  -webkit-backdrop-filter: blur(calc(var(--blur) * .5)) !important;
  background: var(--glass-bg) !important;
  border-top: 1px solid var(--glass-stroke) !important;
}

/* Right column (up next) as floating glass card */
#secondary.ytd-watch-flexy {
  position: sticky;
  top: 72px;
  align-self: flex-start;
}

#secondary-inner {
  border-radius: var(--radius) !important;
  background: var(--card-bg) !important;
  border: 1px solid var(--glass-stroke) !important;
  backdrop-filter: blur(calc(var(--blur) * .6));
  -webkit-backdrop-filter: blur(calc(var(--blur) * .6));
  padding: 12px !important;
  box-shadow: var(--shadow-1);
}

/* Comments */
#comments {
  border-radius: var(--radius) !important;
  background: var(--card-bg) !important;
  border: 1px solid var(--glass-stroke) !important;
  backdrop-filter: blur(calc(var(--blur) * .5));
  -webkit-backdrop-filter: blur(calc(var(--blur) * .5));
  padding: 10px 12px !important;
  box-shadow: var(--shadow-1);
}

/* =========================
   TOP CHIPS / FILTERS
   ========================= */
ytd-feed-filter-chip-bar-renderer, yt-chip-cloud-renderer {
  background: transparent !important;
  border: none !important;
}

yt-chip-cloud-chip-renderer {
  border-radius: 999px !important;
  background: var(--glass-bg) !important;
  border: 1px solid var(--glass-stroke) !important;
  backdrop-filter: blur(calc(var(--blur) * .4));
  -webkit-backdrop-filter: blur(calc(var(--blur) * .4));
}

/* =========================
   BUTTONS & HOVERS
   ========================= */
tp-yt-paper-button, ytd-button-renderer, .yt-spec-button-shape-next {
  border-radius: 999px !important;
}

ytd-button-renderer[is-paper-button] .yt-spec-button-shape-next--tonal,
ytd-button-renderer.style-primary .yt-spec-button-shape-next--mono,
.yt-spec-button-shape-next--tonal {
  background: var(--glass-bg) !important;
  border: 1px solid var(--glass-stroke) !important;
  backdrop-filter: blur(calc(var(--blur) * .4));
  -webkit-backdrop-filter: blur(calc(var(--blur) * .4));
}

ytd-button-renderer:hover .yt-spec-button-shape-next {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(0,0,0,.25);
}

/* Links & active color */
a, #video-title-link, .yt-simple-endpoint {
  color: var(--txt) !important;
}
a:hover {
  color: var(--accent) !important;
}

/* =========================
   MISC CLEANUPS
   ========================= */
ytd-mini-guide-renderer {
  background: transparent !important;
  border: none !important;
}

#chips-wrapper, #header, #contents.ytd-rich-grid-renderer {
  backdrop-filter: none !important; /* keep content crisp */
}

ytd-app[darker-dark-theme] {
  background-color: transparent !important;
}

/* Prevent some solid backplates */
tp-yt-app-drawer, ytd-popup-container, ytd-app[dialog-open] #content {
  background: transparent !important;
}

/* Subscriptions badges look */
ytd-badge-supported-renderer {
  border-radius: 999px !important;
  background: rgba(255,255,255,.08) !important;
  padding: 2px 8px !important;
}

/* Scrollbar (mac-ish thin) */
* {
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.25) transparent;
}
::-webkit-scrollbar {
  height: 10px;
  width: 10px;
}
::-webkit-scrollbar-thumb {
  background-clip: padding-box;
  border-radius: 999px;
  border: 3px solid transparent;
  background-color: rgba(255,255,255,.25);
}
::-webkit-scrollbar-track {
  background: transparent;
}
}
